/**
 * Client Types — Sawaa Dashboard
 *
 * The entity shape is DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change shows up here as a type error instead of drifting
 * silently. Request-payload and query types stay local.
 */

import type { components } from "@/lib/types/api.generated"
import type { PaginatedQuery } from "./common"

type Schemas = components["schemas"]

/** The 16 keys every caller receives (`serializeEmployeeClient`). */
type EmployeeScopedWire = Schemas["EmployeeScopedClientResponseDto"]
/** The full record (`serializeClient`): the 16 keys above plus staff-only ones. */
type ClientWire = Schemas["ClientResponseDto"]
/** Keys the backend withholds from EMPLOYEE-role callers. */
type StaffOnlyKeys = Exclude<keyof ClientWire, keyof EmployeeScopedWire>

/* ─── Entities (derived from OpenAPI) ─── */

/**
 * Dashboard-facing client. The always-present fields are required; the
 * staff-only fields (medical, identity, consent, auth state, ...) are optional
 * because EMPLOYEE-role callers never receive them (GET list/detail return
 * `EmployeeScopedClientResponseDto` for that role).
 *
 * Two documented differences from the wire contract, applied once in
 * `toClient` (`lib/api/clients.ts`) and asserted by
 * `apps/dashboard/test/unit/lib/client-type-contract.spec.ts`:
 *  - `firstName`/`lastName`: the wire allows null (legacy single-name rows);
 *    the dashboard renders them directly and gets "" instead.
 *  - `emailVerified`: the wire sends the verification timestamp (or null) and
 *    only to staff; the dashboard needs the yes/no state and stores a boolean
 *    (false when the field is withheld).
 *
 * Dropped from the old hand-written entity because the API never sends them
 * and nothing reads them: ClientStats, ClientBookingPreview (no endpoint
 * returns either shape).
 */
export type Client = Omit<EmployeeScopedWire, "firstName" | "lastName"> &
  Partial<Omit<Pick<ClientWire, StaffOnlyKeys>, "emailVerified">> & {
    firstName: string
    lastName: string
    emailVerified?: boolean
  }

/* Compile-time guard: every field the API sends exists on `Client`. */
type MissingFromClient = Exclude<keyof ClientWire, keyof Client>
const _clientCoversWireShape: MissingFromClient extends never ? true : MissingFromClient = true
void _clientCoversWireShape

/* ─── Query ─── */

export interface ClientListQuery extends PaginatedQuery {
  sortBy?: "name" | "createdAt" | "isActive"
  sortOrder?: "asc" | "desc"
  search?: string
  isActive?: boolean
}
